"""The CIRCT ``sv`` dialect: SystemVerilog constructs.

Where ``hw`` / ``comb`` / ``seq`` describe a circuit structurally, ``sv``
describes the SystemVerilog a backend would emit: procedural blocks, variables
assigned inside them, continuous assignments, interfaces and generate blocks.
Two consequences shape the operations below.

* They carry *procedural* state (a register's current value, the value driving a
  net) instead of being pure functions of their operands, so ``sv.reg`` has
  ``read``/``write`` where ``comb.add`` only has ``evaluate``.
* Most of them own regions rather than producing results, so the accessors go
  through :meth:`SVOp.region_at`, which tolerates the parser having attached
  only the regions that actually appeared in the text.

They are still :class:`~src.circt.hw_dialect.HWOp` subclasses, so ``truncate``,
``read_operand`` and ``evaluate`` behave exactly as in the other dialects and a
``sv`` operation can be built either from SSA values or from signal names.
"""
from __future__ import annotations

from typing import Any, Dict, List, Optional, Sequence, Tuple, Union

from mlir.ir import (
    Attribute,
    Block,
    Dialect,
    Location,
    Operation,
    Region,
    StringAttr,
    Trait,
    Type,
    Value,
    get_default_context,
)
from .hw_dialect import (
    Direction,
    HWModuleOp,
    HWOp,
    Port,
    SignalEnv,
    bit_width_of,
)

__all__ = [
    "SV_DIALECT",
    "SVOp",
    "SVModuleOp",
    "SVRegOp",
    "SVWireOp",
    "AssignOp",
    "IfOp",
    "AlwaysCombOp",
    "AlwaysFFOp",
    "InterfaceOp",
    "GenerateOp",
]

SV_DIALECT = Dialect("sv", get_default_context())


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _region_of(op: Operation, index: int) -> Region:
    """Return region ``index`` of ``op``, materialising it on demand.

    The parser attaches only the regions it saw in the text, so an ``sv.if``
    read from a file has one region even though the class models two.  Growing
    the list here keeps every region accessor total instead of raising
    ``IndexError`` for the arm that was left out.
    """
    while op.num_regions <= index:
        op.add_region(Region())
    region = op.region(index)
    if not region.blocks:
        region.add_block(Block())
    return region


def _normalise_edge(edge: Optional[str], default: str = "posedge") -> str:
    """Canonicalise an edge keyword to ``"posedge"`` or ``"negedge"``.

    Spellings that are neither (including the empty string) fall back to
    ``default``, because the value can come from a parsed attribute.
    """
    text = str(edge or "").strip().lower()
    if text in ("posedge", "rising", "rise"):
        return "posedge"
    if text in ("negedge", "falling", "fall"):
        return "negedge"
    return default


def _edge_detected(edge: str, previous: int, current: int) -> bool:
    """Whether the two sampled levels form the transition named by ``edge``.

    This is real edge detection rather than a level test: a ``posedge`` block
    fires on 0 -> 1 and stays quiet while the clock sits at 1.
    """
    before = int(previous) & 1
    after = int(current) & 1
    if edge == "negedge":
        return before == 1 and after == 0
    return before == 0 and after == 1


# ---------------------------------------------------------------------------
# Operation base
# ---------------------------------------------------------------------------


class SVOp(HWOp):
    """Shared behaviour for SystemVerilog operations.

    Most ``sv`` operations produce no value and own one region, so the default
    result count is zero and the region helpers below treat region 0 as *the*
    body.  Operations that do define a value (``sv.reg``, ``sv.wire``) override
    :meth:`default_num_results`.
    """

    OPERATION_NAME: Optional[str] = None

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    # -- regions ----------------------------------------------------------
    def region_at(self, index: int) -> Region:
        """Region ``index``, created (with an entry block) if it is missing."""
        return _region_of(self, index)

    def block_at(self, index: int) -> Block:
        return self.region_at(index).blocks[0]

    def ops_at(self, index: int) -> List[Operation]:
        return list(self.block_at(index).operations)

    def append_to(self, index: int, op: Operation) -> Operation:
        return self.block_at(index).append(op)

    @property
    def body_region(self) -> Region:
        return self.region_at(0)

    @property
    def body(self) -> List[Operation]:
        """The operations of the primary region, in textual order."""
        return self.ops_at(0)

    def append(self, op: Operation) -> Operation:
        return self.append_to(0, op)


# ---------------------------------------------------------------------------
# Declarations
# ---------------------------------------------------------------------------


class SVRegOp(SVOp):
    """``%r = sv.reg name "count" : i8`` - a procedural variable.

    In CIRCT the result is an ``!hw.inout`` handle that procedural code reads
    and writes; here the handle *is* the operation, so the value lives on the op
    itself.  :meth:`write` truncates to the declared width, which is how a
    SystemVerilog assignment to a packed variable behaves.
    """

    OPERATION_NAME = "sv.reg"

    #: Class-level defaults so ``build_parsed`` (which skips ``__init__``) works.
    reg_name: str = ""
    current_value: int = 0
    initial_value: int = 0

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        initial_value: int = 0,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("name", StringAttr(name))
        super().__init__(
            result_types=result_types,
            attributes=attrs,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.reg_name = name or ""
        self.initial_value = int(initial_value)
        self.current_value = self.truncate(initial_value)

    @classmethod
    def default_num_results(cls) -> int:
        return 1

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        name_attr = (kwargs.get("attributes") or {}).get("name")
        op.reg_name = name_attr.value if name_attr is not None else op.result_name
        op.initial_value = 0
        op.current_value = 0
        return op

    # -- state ------------------------------------------------------------
    def read(self) -> int:
        return self.truncate(self.current_value)

    def write(self, value: int) -> int:
        """Store ``value``, narrowed to the declared width.  Returns what stuck."""
        self.current_value = self.truncate(value)
        return self.current_value

    def reset_state(self) -> None:
        self.current_value = self.truncate(self.initial_value)

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        """A variable reads as its current contents, whatever the environment."""
        return self.read()


class SVWireOp(SVOp):
    """``%w = sv.wire name "sum" : i8`` - a continuously-driven net.

    A net holds no state: it reports whatever drives it.  The driver is either
    an operand (the structural case, produced by the parser) or a value handed
    to :meth:`assign`, which is what a behaviourally-built circuit uses.
    """

    OPERATION_NAME = "sv.wire"

    #: Class-level defaults so ``build_parsed`` (which skips ``__init__``) works.
    wire_name: str = ""
    driven_value: Optional[int] = None

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        driver: Optional[Union[Value, str, int]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if isinstance(driver, (Value, str)):
            ops.append(driver)
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("name", StringAttr(name))
        super().__init__(
            operands=ops,
            result_types=result_types,
            attributes=attrs,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.wire_name = name or ""
        self.driven_value = self.truncate(driver) if isinstance(driver, int) else None

    @classmethod
    def default_num_results(cls) -> int:
        return 1

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        name_attr = (kwargs.get("attributes") or {}).get("name")
        op.wire_name = name_attr.value if name_attr is not None else op.result_name
        op.driven_value = None
        return op

    # -- driving ----------------------------------------------------------
    @property
    def driver(self) -> Any:
        """The operand driving the net, or ``None`` when :meth:`assign` drives it."""
        return self.get_operand(0) if self.num_operands else None

    @property
    def has_driver(self) -> bool:
        return bool(self.num_operands) or self.driven_value is not None

    def assign(self, value: int) -> int:
        self.driven_value = self.truncate(value)
        return self.driven_value

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        if self.num_operands:
            return self.truncate(self.read_operand(env or {}, 0))
        return self.truncate(self.driven_value or 0)


class AssignOp(SVOp):
    """``sv.assign %dest, %src : i8`` - a continuous assignment.

    :meth:`apply` is the whole of its semantics: read the source and narrow it
    to the destination's width.  The width comes from the destination operand
    because the assignment itself has no result type to read.
    """

    OPERATION_NAME = "sv.assign"

    #: Operand indices, in CIRCT's order.
    DESTINATION = 0
    SOURCE = 1

    def __init__(
        self,
        destination: Optional[Union[Value, str]] = None,
        source: Optional[Union[Value, str]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if destination is not None:
                ops.append(destination)
            if source is not None:
                ops.append(source)
        super().__init__(operands=ops, attributes=attributes, location=location)

    # -- operand accessors -------------------------------------------------
    @property
    def destination(self) -> Any:
        if self.num_operands <= self.DESTINATION:
            return None
        return self.get_operand(self.DESTINATION)

    @property
    def source(self) -> Any:
        if self.num_operands <= self.SOURCE:
            return None
        return self.get_operand(self.SOURCE)

    def destination_width(self) -> int:
        """The width the assignment narrows to, taken from the destination.

        An ``!hw.inout<i8>`` destination reports no width of its own, so the
        declaring ``sv.reg`` / ``sv.wire`` is asked instead.
        """
        values = self.ssa_operands
        if len(values) > self.DESTINATION:
            target = values[self.DESTINATION]
            width = bit_width_of(target.type)
            if width:
                return width
            defining = target.defining_op
            if isinstance(defining, HWOp):
                return defining.width
        return self.width

    # -- evaluation --------------------------------------------------------
    def apply(self, env: Optional[SignalEnv] = None) -> int:
        """The value this assignment drives onto its destination."""
        value = self.read_operand(env or {}, self.SOURCE)
        width = self.destination_width()
        return value & ((1 << width) - 1) if width > 0 else int(value)

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        return self.apply(env)

    def verify_op(self) -> List[str]:
        if self.num_operands < 2:
            return ["'sv.assign' expects a destination and a source operand"]
        return []


# ---------------------------------------------------------------------------
# Procedural blocks
# ---------------------------------------------------------------------------


class IfOp(SVOp):
    """``sv.if %cond { ... } else { ... }`` - a procedural conditional.

    Region 0 is the ``then`` arm and region 1 the ``else`` arm; an ``sv.if``
    without an else arm simply has an empty second region.
    """

    OPERATION_NAME = "sv.if"
    TRAITS = (Trait.SINGLE_BLOCK, Trait.NO_TERMINATOR)

    #: Region indices.
    THEN = 0
    ELSE = 1

    def __init__(
        self,
        condition: Optional[Union[Value, str]] = None,
        then_body: Optional[Sequence[Operation]] = None,
        else_body: Optional[Sequence[Operation]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops and condition is not None:
            ops.append(condition)
        super().__init__(operands=ops, attributes=attributes, location=location)
        # Materialise both arms up front so region 1 always means ``else``.
        self.region_at(self.ELSE)
        for op in then_body or ():
            self.append_then(op)
        for op in else_body or ():
            self.append_else(op)

    # -- structure --------------------------------------------------------
    @property
    def condition(self) -> Any:
        return self.get_operand(0) if self.num_operands else None

    @property
    def then_region(self) -> Region:
        return self.region_at(self.THEN)

    @property
    def else_region(self) -> Region:
        return self.region_at(self.ELSE)

    @property
    def then_body(self) -> List[Operation]:
        return self.ops_at(self.THEN)

    @property
    def else_body(self) -> List[Operation]:
        return self.ops_at(self.ELSE)

    @property
    def has_else(self) -> bool:
        return bool(self.else_body)

    def append_then(self, op: Operation) -> Operation:
        return self.append_to(self.THEN, op)

    def append_else(self, op: Operation) -> Operation:
        return self.append_to(self.ELSE, op)

    # -- evaluation --------------------------------------------------------
    def condition_value(self, env: Optional[SignalEnv] = None) -> int:
        return self.read_operand(env or {}, 0) & 1

    def taken_branch(self, env: Optional[SignalEnv] = None) -> str:
        """``"then"`` or ``"else"``, according to the condition in ``env``."""
        return "then" if self.condition_value(env) else "else"

    def taken_body(self, env: Optional[SignalEnv] = None) -> List[Operation]:
        """The operations the conditional actually executes in ``env``."""
        return self.then_body if self.condition_value(env) else self.else_body


class AlwaysCombOp(SVOp):
    """``sv.alwayscomb { ... }`` - a combinational procedural block.

    Its body re-executes whenever anything it reads changes, so there is no
    clock and nothing to detect: the block owns one region and that is all.
    """

    OPERATION_NAME = "sv.alwayscomb"
    TRAITS = (Trait.SINGLE_BLOCK, Trait.NO_TERMINATOR)

    def __init__(
        self,
        body: Optional[Sequence[Operation]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(operands=operands, attributes=attributes, location=location)
        self.region_at(0)
        for op in body or ():
            self.append(op)


class AlwaysFFOp(SVOp):
    """``sv.alwaysff(posedge %clk) { ... }`` - a clocked procedural block.

    Operand order is ``(clock[, reset])``.  The sensitivity is an edge, not a
    level, so :meth:`triggers_on` takes the previously sampled clock alongside
    the current one - the same two-phase view of a cycle that
    :class:`~src.circt.seq_dialect.SeqOp` takes.
    """

    OPERATION_NAME = "sv.alwaysff"
    TRAITS = (Trait.SINGLE_BLOCK, Trait.NO_TERMINATOR, Trait.HAS_CLOCK)

    #: Operand indices.
    CLOCK = 0
    RESET = 1

    #: Class-level defaults so ``build_parsed`` (which skips ``__init__``) works.
    clock_edge: str = "posedge"
    reset_edge: str = ""

    def __init__(
        self,
        clock: Optional[Union[Value, str]] = None,
        clock_edge: str = "posedge",
        reset: Optional[Union[Value, str]] = None,
        reset_edge: str = "",
        body: Optional[Sequence[Operation]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if clock is not None:
                ops.append(clock)
            if reset is not None:
                ops.append(reset)
        edge = _normalise_edge(clock_edge)
        # A reset operand with no explicit edge is sampled on its rising edge.
        has_reset = len(ops) > self.RESET
        reset_edge_name = _normalise_edge(reset_edge) if has_reset or reset_edge else ""
        attrs: Dict[str, Attribute] = dict(attributes or {})
        attrs.setdefault("clockEdge", StringAttr(edge))
        if reset_edge_name:
            attrs.setdefault("resetEdge", StringAttr(reset_edge_name))
        super().__init__(operands=ops, attributes=attrs, location=location)
        self.clock_edge = edge
        self.reset_edge = reset_edge_name
        self.region_at(0)
        for op in body or ():
            self.append(op)

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        attrs = kwargs.get("attributes") or {}
        clock_attr = attrs.get("clockEdge")
        reset_attr = attrs.get("resetEdge")
        op.clock_edge = _normalise_edge(clock_attr.value) if clock_attr else "posedge"
        op.reset_edge = _normalise_edge(reset_attr.value) if reset_attr else ""
        return op

    # -- operand accessors -------------------------------------------------
    @property
    def clock(self) -> Any:
        if self.num_operands <= self.CLOCK:
            return None
        return self.get_operand(self.CLOCK)

    @property
    def has_reset(self) -> bool:
        return self.num_operands > self.RESET

    @property
    def reset(self) -> Any:
        return self.get_operand(self.RESET) if self.has_reset else None

    # -- edge detection ----------------------------------------------------
    def triggers_on(self, previous_clock: int, current_clock: int) -> bool:
        """Whether the clock made the transition this block is sensitive to."""
        return _edge_detected(self.clock_edge, previous_clock, current_clock)

    def reset_triggers_on(self, previous_reset: int, current_reset: int) -> bool:
        """Same test for the reset, or ``False`` when the block has no reset."""
        if not self.reset_edge:
            return False
        return _edge_detected(self.reset_edge, previous_reset, current_reset)


# ---------------------------------------------------------------------------
# Elaboration-time constructs
# ---------------------------------------------------------------------------


class InterfaceOp(SVOp):
    """``sv.interface @Bus { ... }`` - a named bundle of signals.

    An interface only declares ``(name, type)`` pairs, so the list lives on the
    operation as plain Python data: that makes :meth:`get_signal` a lookup
    rather than a walk over nested declaration operations.
    """

    OPERATION_NAME = "sv.interface"
    TRAITS = (Trait.SYMBOL,)

    #: Class-level defaults so ``build_parsed`` (which skips ``__init__``) works.
    interface_name: str = ""
    signals: Sequence[Tuple[str, Optional[Type]]] = ()

    def __init__(
        self,
        name: Optional[str] = None,
        signals: Optional[Sequence[Tuple[str, Optional[Type]]]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("sym_name", StringAttr(name))
        super().__init__(attributes=attrs, location=location)
        self.interface_name = name or ""
        self.signals = [(str(sig), sig_type) for sig, sig_type in (signals or ())]

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        name_attr = (kwargs.get("attributes") or {}).get("sym_name")
        op.interface_name = name_attr.value if name_attr is not None else ""
        op.signals = []
        return op

    @property
    def sym_name(self) -> Optional[str]:
        return self.interface_name or None

    # -- signals ----------------------------------------------------------
    def signal_names(self) -> List[str]:
        return [name for name, _ in self.signals]

    def has_signal(self, name: str) -> bool:
        return name in self.signal_names()

    def get_signal(self, name: str) -> Optional[Type]:
        """The declared type of ``name``, or ``None`` if there is no such signal."""
        for signal_name, signal_type in self.signals:
            if signal_name == name:
                return signal_type
        return None

    def add_signal(
        self, name: str, type: Optional[Type] = None
    ) -> Tuple[str, Optional[Type]]:
        signal = (str(name), type)
        # Rebind instead of appending: the class-level default is an immutable
        # empty tuple, so appending in place would be shared by every instance.
        self.signals = list(self.signals) + [signal]
        return signal


class GenerateOp(SVOp):
    """``sv.generate "label" { ... }`` - an elaboration-time block.

    The label names the emitted generate block, so it is kept in an attribute
    and therefore survives a print/parse round trip.
    """

    OPERATION_NAME = "sv.generate"
    TRAITS = (Trait.SINGLE_BLOCK, Trait.NO_TERMINATOR)

    def __init__(
        self,
        label: Optional[str] = None,
        body: Optional[Sequence[Operation]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if label:
            attrs.setdefault("label", StringAttr(label))
        super().__init__(attributes=attrs, location=location)
        self.region_at(0)
        for op in body or ():
            self.append(op)

    @property
    def label(self) -> str:
        attr = self.attributes.get("label")
        return attr.value if attr is not None else ""


# ---------------------------------------------------------------------------
# Modules
# ---------------------------------------------------------------------------


class SVModuleOp(HWModuleOp):
    """``sv.module @Name(in %a: i8, out b: i8) { ... }``.

    A SystemVerilog module has exactly the port structure of an ``hw.module``,
    so this reuses :class:`~src.circt.hw_dialect.HWModuleOp`'s port encoding
    (``port_names`` / ``port_directions`` / ``function_type``) together with its
    ``ports`` / ``input_ports`` / ``output_ports`` / ``get_port`` accessors and
    :class:`~src.circt.hw_dialect.Port` itself.  What it deliberately does not
    inherit is the signature verification: an ``sv.module`` body is procedural,
    so it is not terminated by ``hw.output`` and its ports may be zero-width.
    """

    OPERATION_NAME = "sv.module"
    TRAITS = (
        Trait.SYMBOL,
        Trait.ISOLATED_FROM_ABOVE,
        Trait.GRAPH_REGION,
        Trait.SINGLE_BLOCK,
    )

    # -- structure --------------------------------------------------------
    @property
    def body_region(self) -> Region:
        return _region_of(self, 0)

    def append(self, op: Operation) -> Operation:
        return self.body_region.blocks[0].append(op)

    def ports_with_direction(self, direction: Union[str, Direction]) -> List[Port]:
        """Every port facing ``direction`` (which may be spelled ``"in"``)."""
        wanted = Direction.parse(direction)
        return [port for port in self.ports if port.direction is wanted]

    # -- verification -----------------------------------------------------
    def verify_op(self) -> List[str]:
        if self.module_name is None:
            return [f"'{self.OPERATION_NAME}' requires a 'sym_name' attribute"]
        return []


for _op in (
    SVModuleOp,
    SVRegOp,
    SVWireOp,
    AssignOp,
    IfOp,
    AlwaysCombOp,
    AlwaysFFOp,
    InterfaceOp,
    GenerateOp,
):
    SV_DIALECT.register_operation(_op)
del _op

